import asyncio
import unittest


async def job(name, fail):
    await asyncio.sleep(0)
    if fail:
        raise ValueError(name + " failed")
    return name


async def slow_job(name):
    await asyncio.sleep(0.05)
    return name


async def collect_all(jobs, job_func=job):
    results = await asyncio.gather(*(job_func(name, fail) for name, fail in jobs), return_exceptions=True)
    values = [item for item in results if not isinstance(item, BaseException)]
    errors = [str(item) for item in results if isinstance(item, BaseException)]
    return {"values": values, "errors": errors}


async def collect_all_structured(jobs, job_func=job):
    values = []
    errors = []
    try:
        async with asyncio.TaskGroup() as group:
            tasks = [group.create_task(job_func(name, fail)) for name, fail in jobs]
    except* ValueError:
        pass
    for task in tasks:
        if task.cancelled():
            continue
        error = task.exception()
        if error is None:
            values.append(task.result())
        else:
            errors.append(str(error))
    return {"values": values, "errors": errors}


def with_a_slow_sibling(name, fail):
    if name == "slow":
        return slow_job(name)
    return job(name, fail)


class GatherTest(unittest.TestCase):
    def test_gather_collects_every_failure(self):
        report = asyncio.run(collect_all([("a", True), ("b", True), ("c", False)]))
        self.assertEqual(report["errors"], ["a failed", "b failed"])
        self.assertEqual(report["values"], ["c"])

    def test_task_group_matches_gather_on_quick_jobs(self):
        jobs = [("z", True), ("a", True), ("m", False)]
        self.assertEqual(asyncio.run(collect_all_structured(jobs)), asyncio.run(collect_all(jobs)))

    def test_task_group_cancels_slow_siblings_gather_keeps_them(self):
        jobs = [("slow", False), ("quick", True)]
        gather_report = asyncio.run(collect_all(jobs, with_a_slow_sibling))
        structured_report = asyncio.run(collect_all_structured(jobs, with_a_slow_sibling))
        self.assertEqual(gather_report["values"], ["slow"])
        self.assertEqual(gather_report["errors"], ["quick failed"])
        self.assertEqual(structured_report["values"], [])
        self.assertEqual(structured_report["errors"], ["quick failed"])

    def test_success_order_follows_input(self):
        report = asyncio.run(collect_all([("first", False), ("second", False)]))
        self.assertEqual(report["values"], ["first", "second"])
        self.assertEqual(report["errors"], [])

    def test_no_pending_task_survives(self):
        async def scenario():
            await collect_all([("a", True), ("b", False)])
            await collect_all_structured([("a", True), ("b", False)])
            current = asyncio.current_task()
            return [task for task in asyncio.all_tasks() if task is not current]

        self.assertEqual(asyncio.run(scenario()), [])


if __name__ == "__main__":
    unittest.main()

import asyncio
import unittest


async def job(name, fail):
    await asyncio.sleep(0)
    if fail:
        raise ValueError(name + " failed")
    return name


async def retrieve_all(jobs):
    outcomes = await asyncio.gather(*(job(name, fail) for name, fail in jobs), return_exceptions=True)
    ok = {}
    failed = {}
    for (name, _), outcome in zip(jobs, outcomes):
        if isinstance(outcome, BaseException):
            failed[name] = (type(outcome).__name__, str(outcome))
        else:
            ok[name] = outcome
    current = asyncio.current_task()
    pending = [task for task in asyncio.all_tasks() if task is not current]
    return {"ok": ok, "failed": failed}, len(pending)


async def cancel_unretrieved():
    task = asyncio.create_task(job("z", True))
    await asyncio.sleep(0)
    task.cancel()
    try:
        await task
    except asyncio.CancelledError:
        pass
    try:
        captured = task.exception()
    except asyncio.CancelledError as error:
        captured = error
    return task, captured


class ExceptionNotRetrievedTest(unittest.TestCase):
    def test_outcomes_are_split_and_nothing_is_left(self):
        report, unretrieved = asyncio.run(retrieve_all([("a", True), ("b", False)]))
        self.assertEqual(sorted(report["ok"]), ["b"])
        self.assertEqual(report["failed"]["a"], ("ValueError", "a failed"))
        self.assertEqual(unretrieved, 0)

    def test_cancelled_task_exception_raises_cancelled_error(self):
        task, captured = asyncio.run(cancel_unretrieved())
        self.assertTrue(task.cancelled())
        self.assertIsInstance(captured, asyncio.CancelledError)
        with self.assertRaises(asyncio.CancelledError):
            task.exception()

    def test_all_success_needs_no_retrieval(self):
        report, unretrieved = asyncio.run(retrieve_all([("a", False)]))
        self.assertEqual(report["failed"], {})
        self.assertEqual(unretrieved, 0)


if __name__ == "__main__":
    unittest.main()

