import asyncio


async def job(name, fail):
    await asyncio.sleep(0)
    if fail:
        raise ValueError(name + " failed")
    return name


async def main():
    raw = await asyncio.gather(job("a", True), job("b", False), return_exceptions=True)
    ok = {}
    failed = {}
    for name, outcome in zip(("a", "b"), raw):
        if outcome:
            ok[name] = outcome
        else:
            failed[name] = str(outcome)
    print("ok:", sorted(ok), "failed:", sorted(failed))


asyncio.run(main())
